1	export type Cell = [number, number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function isNeighborOf(cell: Cell, other: Cell): boolean {
8	  const [x, y] = cell;
9	  const [otherX, otherY] = other;
10	  return (
11	    !isSameCell(cell, other) &&
12	    Math.abs(otherX - x) <= 1 &&
13	    Math.abs(otherY - y) <= 1
14	  );
15	}
16	
17	function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
18	  return liveCells.filter((other) => isNeighborOf(cell, other)).length;
19	}
20	
21	function survives(cell: Cell, liveCells: Cell[]): boolean {
22	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
23	  return liveNeighbors === 2 || liveNeighbors === 3;
24	}
25	
26	const NEIGHBOR_OFFSETS = [-1, 0, 1];
27	
28	function isBorn(cell: Cell, liveCells: Cell[]): boolean {
29	  return countLiveNeighbors(cell, liveCells) === 3;
30	}
31	
32	function deadNeighborsOf(liveCells: Cell[]): Cell[] {
33	  const candidates: Cell[] = [];
34	  for (const [x, y] of liveCells) {
35	    for (const dx of NEIGHBOR_OFFSETS) {
36	      for (const dy of NEIGHBOR_OFFSETS) {
37	        const candidate: Cell = [x + dx, y + dy];
38	        const isAlive = liveCells.some((live) => isSameCell(candidate, live));
39	        const alreadyFound = candidates.some((found) =>
40	          isSameCell(candidate, found),
41	        );
42	        if (!isAlive && !alreadyFound) candidates.push(candidate);
43	      }
44	    }
45	  }
46	  return candidates;
47	}
48	
49	export function nextGeneration(liveCells: Cell[]): Cell[] {
50	  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
51	  const births = deadNeighborsOf(liveCells).filter((cell) =>
52	    isBorn(cell, liveCells),
53	  );
54	  return [...survivors, ...births];
55	}
