const CELL_DELTAS = [-1, 0, 1];

function neighborsOf([x, y]: Cell): Cell[] {
  return CELL_DELTAS.flatMap((dx) =>
    CELL_DELTAS.map((dy): Cell => [x + dx, y + dy]),
  ).filter((neighbor) => !isSameCell(neighbor, [x, y]));
}

function deduplicate(cells: Cell[]): Cell[] {
  return cells.filter(
    (cell, index) => !contains(cells.slice(0, index), cell),
  );
}

function deadNeighborsOf(liveCells: Cell[]): Cell[] {
  const allNeighbors = liveCells.flatMap(neighborsOf);
  return deduplicate(allNeighbors).filter(
    (neighbor) => !contains(liveCells, neighbor),
  );
}

